__NUXT_JSONP__("/th/firstday-at-mli", (function(a){return {data:[{details:{slug:"th",pageTitle:"วันแรกที่ MLI | Mentor Language Institute",pageDescription:a,title:"วันแรกที่ MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffirst-day-at-mli\u002Fmli-signup.jpg",categories:[{title:"ยินดีต้อนรับสู่ Mentor Language Institute",description:[a,"การปฐมนิเทศเป็นการแจ้งข้อมูลที่สำคัญและจำเป็นแก่ท่าน เพื่อเพิ่มพูนความเข้าใจเกี่ยวกับหลักสูตร กฎระเบียบด้านการเข้าเมืองและกฎระเบียบของโรงเรียน ตลอดจนช่วยให้ท่านบรรลุวัตถุประสงค์ทางวิชาการทั้งหมด \u003Cbr \u002F\u003Eท่านจะได้รับการต้อนรับที่อบอุ่นจากเจ้าหน้าที่ของเรา"],dates:["＜วันที่เริ่มต้นของแต่ละเทอม (คริสต์ศักราช)＞","- May 22nd, 2023 \u003Cbr\u002F\u003E - June 20th, 2023 \u003Cbr\u002F\u003E - July 17th, 2023 \u003Cbr\u002F\u003E - August 14th, 2023 \u003Cbr\u002F\u003E - September 11th, 2023 \u003Cbr\u002F\u003E - October 10th, 2023 \u003Cbr\u002F\u003E - November 6th, 2023 \u003Cbr\u002F\u003E - December 4th, 2023 \u003Cbr\u002F\u003E - January 8th, 2024 \u003Cbr\u002F\u003E - February 5th, 2024 \u003Cbr\u002F\u003E - March 4th, 2024","การปฐมนิเทศเริ่มตั้งแต่เวลา 13:00 น."],groups:[{title:"การปฐมนิเทศและผลการทดสอบ",listType:"table",lists:[{key:"13:00pm – 13:30pm",value:"รับเอกสารและลงทะเบียน"},{key:"13:30pm – 14:00pm",value:"เข้าฟังการปฐมนิเทศเชิงวิชาการ"},{key:"14:00pm – 15:00pm",value:"ทำแบบทดสอบ"},{key:"15:15pm – 15:35pm",value:"รับฟังนโยบายโรงเรียนและกฎการเข้าเมือง"},{key:"15:35pm – 15:50pm",value:"บริการโอนย้ายเข้าศึกษาต่อในระดับวิทยาลัย"},{key:"15:50pm – 16:00pm",value:"รับฟังข้อมูลเกี่ยวกับกิจกรรมและหอพัก"},{key:"16:00pm – 16:10pm",value:"การสอบพูดและการจัดชั้นเรียน"},{key:"16:10pm – 16:20pm",value:"ชำระค่าหนังสือเรียน"}]},{title:"สิ่งที่ต้องนำมาในวันปฐมนิเทศ",lists:["หนังสือเดินทาง (หากคุณเป็นผู้ถือวีซ่านักเรียน)","I-20 (หากคุณเป็นผู้ถือวีซ่านักเรียน)","ปากกาและกระดาษ","ค่าหนังสือเรียนและการชำระค่าเล่าเรียน"]}]},{title:"รายละเอียด",groups:[{title:"ตารางการปฐมนิเทศ",description:["ท่านต้องกรอกข้อมูลลงในใบลงทะเบียน\u003Cbr \u002F\u003Eจากนั้นผู้อำนวยการฝ่ายการศึกษาจะให้ข้อมูลเกี่ยวกับความแตกต่างของแต่ละชั้นเรียน\u003Cbr \u002F\u003Eผู้เรียนจะสามารถย้ายขึ้นไประดับที่ยากกว่าได้จากผลการเรียน"]},{title:"ทำแบบทดสอบและสัมภาษณ์",description:["หลังจากการปฐมนิเทศท่านจะได้รับ \"การทดสอบวัดระดับภาษาอังกฤษ\" ซึ่งเป็นข้อคำถาม 80 ข้อ โดยมีส่วนของการฟังและการเขียนที่ครอบคลุมไวยากรณ์ คำศัพท์และการอ่าน ภายในเวลา 60 นาที เพื่อช่วยในการกำหนดระดับภาษาอังกฤษของท่าน\u003Cbr \u002F\u003Eหลังจากการทดสอบท่านจะได้รับการทดสอบการพูดอย่างรวดเร็ว (การสัมภาษณ์) กับหนึ่งในผู้สอนของเรา (ทั้ง PC, AD หรือผู้สอนของ MLI)\u003Cbr \u002F\u003Eการทดสอบนี้จะช่วยกำหนดระดับและ\u002Fหรือหลักสูตรที่เหมาะสมที่สุดตามทักษะและเป้าหมายของท่าน"]},{title:"การชำระค่าหนังสือเรียน",description:["หลังการทดสอบและการสัมภาษณ์ ผู้เรียนจะซื้อหนังสือจากเจ้าหน้าที่ ซึ่งท่านสามารถถามคำถามหรือข้อสงสัยอื่นๆเพิ่มเติมกับทางเจ้าหน้าที่ได้"]}]}],dir:"\u002Ffirstday-at-mli",path:"\u002Ffirstday-at-mli\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:29.270Z",updatedAt:"2025-05-26T12:06:27.758Z"}}],fetch:{},mutations:void 0}}("MLI จะมีการปฐมนิเทศนักเรียนใหม่ในตอนต้นภาคเรียน (ทุก 4 สัปดาห์)")));